  export interface SpawnSyncReturns {
    status: number | null;
    stdout: string;
    stderr: string;
    error?: Error;
  }
  export function spawnSync(
    command: string,
    args: string[],
    options: { input?: string; encoding: "utf8"; env?: Record<string, string | undefined> },
  ): SpawnSyncReturns;
}

